-- TradeSight Export Analytics: baseline SQL queries
-- Run against the SQLite database generated by scripts/run_pipeline.py.

-- 1. Overall baseline metrics
SELECT
    COUNT(*) AS total_orders,
    ROUND(SUM(total_value_inr), 2) AS total_order_value_inr,
    ROUND(AVG(total_value_inr), 2) AS average_order_value_inr,
    SUM(quantity_units) AS total_quantity_units,
    ROUND(AVG(delivery_days), 2) AS average_delivery_days,
    ROUND(AVG(on_time_delivery) * 100, 2) AS on_time_delivery_rate_pct,
    SUM(return_qty) AS total_return_quantity,
    ROUND(SUM(return_qty) * 100.0 / NULLIF(SUM(quantity_units), 0), 2) AS return_to_quantity_rate_pct,
    ROUND(AVG(repeat_buyer) * 100, 2) AS repeat_buyer_order_rate_pct
FROM orders;

-- 2. Monthly order trend
SELECT strftime('%Y-%m', order_date) AS order_month,
       COUNT(*) AS total_orders,
       ROUND(SUM(total_value_inr), 2) AS total_value_inr
FROM orders
GROUP BY strftime('%Y-%m', order_date)
ORDER BY order_month;

-- 3. Category performance
SELECT category, COUNT(*) AS total_orders,
       ROUND(SUM(total_value_inr), 2) AS total_value_inr,
       ROUND(AVG(delivery_days), 2) AS avg_delivery_days
FROM orders
GROUP BY category
ORDER BY total_value_inr DESC;

-- 4. Top 10 buyers by order value
SELECT buyer_id, COUNT(*) AS total_orders,
       ROUND(SUM(total_value_inr), 2) AS total_value_inr
FROM orders
GROUP BY buyer_id
ORDER BY total_value_inr DESC
LIMIT 10;

-- 5. Top 10 sellers by order value
SELECT seller_id, COUNT(*) AS total_orders,
       ROUND(SUM(total_value_inr), 2) AS total_value_inr
FROM orders
GROUP BY seller_id
ORDER BY total_value_inr DESC
LIMIT 10;

-- 6. Delivery performance by seller
SELECT seller_id, COUNT(*) AS total_orders,
       ROUND(AVG(delivery_days), 2) AS avg_delivery_days,
       ROUND(AVG(on_time_delivery) * 100, 2) AS on_time_rate_pct
FROM orders
GROUP BY seller_id
ORDER BY on_time_rate_pct DESC;
